cssCode:
.petal {
  position: absolute; width: 15px; height: 15px;
  background: #ff4d6d;
  border-radius: 50% 0 50% 50%;
  opacity: 0.7; box-shadow: 0 0 10px rgba(255, 77, 109, 0.5);
  animation: fallPetal linear infinite;
}
@keyframes fallPetal {
  0% { transform: translateY(-20px) rotate(0deg); opacity: 0; }
  20% { opacity: 0.7; }
  80% { opacity: 0.7; }
  100% { transform: translateY(300px) rotate(360deg); opacity: 0; }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;';

for(let i=0; i<15; i++) {
  const petal = document.createElement('div');
  petal.className = 'petal';
  petal.style.left = `${Math.random() * 100}%`;
  petal.style.animationDuration = `${3 + Math.random() * 4}s`;
  petal.style.animationDelay = `${Math.random() * 5}s`;
  c.appendChild(petal);
}
